-- Applied to project gdwhcjwenuwloglivgis on 2026-11-21. Closed foundation; no real accounts or data.
begin;
create table public.g11_locations(id uuid primary key default gen_random_uuid(),code text unique not null,name text not null,active boolean not null default true);
create table public.g11_profiles(id uuid primary key references auth.users(id),sendys text unique not null check(length(trim(sendys))>0),first_name text not null,last_name text not null,role text not null default 'colaborador' check(role in ('colaborador','supervisor','admin')),active boolean not null default false,must_change_password boolean not null default true,created_at timestamptz not null default now());
create table public.g11_assignments(profile_id uuid references public.g11_profiles(id),location_id uuid references public.g11_locations(id),primary key(profile_id,location_id));
create table public.g11_sessions(id uuid primary key default gen_random_uuid(),title text not null,starts_at timestamptz not null,ends_at timestamptz not null,teams_url text,published boolean not null default false,created_by uuid references public.g11_profiles(id),check(ends_at>starts_at));
create table public.g11_occurrences(id uuid primary key default gen_random_uuid(),location_id uuid not null references public.g11_locations(id),reported_by uuid not null references public.g11_profiles(id),occurred_at timestamptz not null,category text not null,description text not null,status text not null default 'aberta' check(status in ('aberta','em_tratamento','resolvida')),created_at timestamptz not null default now());
create table public.g11_audits(id uuid primary key default gen_random_uuid(),location_id uuid not null references public.g11_locations(id),entity text not null,conducted_on date,next_on date,report_path text,created_by uuid references public.g11_profiles(id));
create table public.g11_training_records(id uuid primary key default gen_random_uuid(),profile_id uuid not null references public.g11_profiles(id),location_id uuid references public.g11_locations(id),module_code text not null,activity_type text not null check(activity_type in ('flash','modulo','presenca')),status text not null default 'por_validar',recorded_by uuid references public.g11_profiles(id),created_at timestamptz not null default now());
create table public.g11_assessment_attempts(id uuid primary key default gen_random_uuid(),profile_id uuid not null references public.g11_profiles(id),module_code text not null check(module_code in ('M01','M02')),attempt_no smallint not null check(attempt_no between 1 and 2),earned numeric not null,total numeric not null,review_confirmed boolean not null default false,source_reference text unique not null,status text not null default 'por_validar' check(status in ('por_validar','validada','anulada')),imported_by uuid references public.g11_profiles(id),created_at timestamptz not null default now(),unique(profile_id,module_code,attempt_no),check(total>0 and earned>=0 and earned<=total),check(attempt_no=1 or review_confirmed));
create table public.g11_certificates(id uuid primary key default gen_random_uuid(),profile_id uuid not null references public.g11_profiles(id),module_code text not null,document_path text,status text not null default 'rascunho' check(status in ('rascunho','validado','emitido','revogado')),validated_by uuid references public.g11_profiles(id),issued_at timestamptz);
do $$ declare t text; begin foreach t in array array['g11_locations','g11_profiles','g11_assignments','g11_sessions','g11_occurrences','g11_audits','g11_training_records','g11_assessment_attempts','g11_certificates'] loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on table public.%I from anon, authenticated',t); end loop; end $$;
commit;
select count(*) as tables_created,bool_and(c.relrowsecurity) as all_rls_enabled from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and c.relname like 'g11_%';
